def differentiate(polynomial: str, x: int) -> int:
    # Split the polynomial into terms
    terms = polynomial.replace('-', '+-').split('+')
    derivative_terms = []

    for term in terms:
        if 'x' in term:
            if '^' in term:
                coefficient, exponent = term.split('x^')
                coefficient = int(coefficient) if coefficient and coefficient != '-' else (1 if coefficient != '-' else -1)
                exponent = int(exponent)
                derived_coefficient = coefficient * exponent
                derived_exponent = exponent - 1
                if derived_exponent == 0:
                    derivative_terms.append(str(derived_coefficient))
                else:
                    derivative_terms.append(f'{derived_coefficient}x^{derived_exponent}')
            else:
                coefficient = term.replace('x', '')
                coefficient = int(coefficient) if coefficient and coefficient != '-' else (1 if coefficient != '-' else -1)
                derived_coefficient = coefficient
                derived_exponent = 1
                derivative_terms.append(f'{derived_coefficient}x')
        elif term == '' or term == '-':
            continue
        else:
            # Constant term, derivative is 0
            continue

    # Evaluate the derivative at the given point x
    derivative_expression = '+'.join(derivative_terms).replace('+-', '-')
    if 'x' in derivative_expression:
        derivative_expression = derivative_expression.replace('x', f'*{x}')
    else:
        derivative_expression = f'{derivative_expression}*{x}'
    return eval(derivative_expression)

# Example usage:
